'use strict';
const keepSceneGoing=storyButton('Keep scene going',()=>copyTimelineScene(sceneIndex,true).catch(e=>toast(e.message)),'Make the next scene with this background and the characters in their ending positions.');keepSceneGoing.id='keepSceneGoing';document.querySelector('.stage-actions').prepend(keepSceneGoing);
const plainWorkspaceNames={continueSceneNext:'Keep scene going',copySceneNext:'Copy this scene',applySceneContinuity:'Keep character going',openSceneContinuity:'Keep character going',applySceneBoundary:'Use this change',previewSceneBoundary:'Preview change',timelineSceneTransition:'Change between scenes',openNarratorVoice:'Voice',replaceNarrationSection:'Change this voice section',replaceCharacterArtFile:'Replace character picture',applyAnimationReview:'Keep these changes',cancelAnimationReview:'Go back',existingGrip:'Saved hand positions',existingGripX:'Hand position across',existingGripY:'Hand position up/down',existingGripAngle:'Object angle'};
for(const [id,text]of Object.entries(plainWorkspaceNames)){const el=$(id);if(!el)continue;if(el.matches('button'))el.textContent=text;el.setAttribute('aria-label',text)}
function plainStudioWords(text){return text.replace(/\bretime\b/gi,'adjust timing').replace(/\bretiming\b/gi,'adjusting timing').replace(/\bopacity\b/gi,'visibility').replace(/\bphonetic\b/gi,'speech sound').replace(/\bgrip placement\b/gi,'hand position').replace(/\bcut-out\b/gi,'picture part').replace(/\bsource coordinates\b/gi,'original timing').replace(/\bsynthesis\b/gi,'voice generation').replace(/\bnarration sections\b/gi,'voice sections')}
function simplifyWorkspaceLabels(root=document){for(const el of root.querySelectorAll('label,summary,button,option,.note')){if(el.closest('#castList,#projectList,#rigLibrary,.story-line-heading,.timeline-clip')||el.isContentEditable)continue;for(const node of el.childNodes)if(node.nodeType===Node.TEXT_NODE){const next=plainStudioWords(node.textContent);if(next!==node.textContent)node.textContent=next}if(el.title)el.title=plainStudioWords(el.title)}for(const el of document.querySelectorAll('#transition option,#sceneBoundaryType option')){const names={cut:'No effect',crossfade:'Blend scenes',fade:'Fade through background',match:'Match pictures','slide-left':'Slide left','slide-right':'Slide right',zoom:'Zoom between scenes'};if(names[el.value]&&el.textContent!==names[el.value])el.textContent=names[el.value]}}
simplifyWorkspaceLabels();let plainWorkspaceTimer;new MutationObserver(()=>{clearTimeout(plainWorkspaceTimer);plainWorkspaceTimer=setTimeout(()=>simplifyWorkspaceLabels(),80)}).observe(document.body,{childList:true,subtree:true});

const viewBeforeContinuation=characterViewAt;characterViewAt=function(o,t=time){return(o.viewKeys||[]).some(k=>k.t<=t+.00001)?viewBeforeContinuation(o,t):o.defaultCharacterView||'front'};const snapshotBeforeViewContinuation=continuitySnapshot;continuitySnapshot=function(o,s,at){const copy=snapshotBeforeViewContinuation(o,s,at);if(o.type==='puppet')copy.defaultCharacterView=characterViewAt(o,at);return copy};
